import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        // set up initial owner
        c = new C();
        c.transferOwnership(newOwner);
        // record owner before calling owned
        address ownerBefore = c.owner();
        // try to call owned as caller
        bool ok;
        vm.prank(caller);
        try c.owned() { ok = true; } catch { ok = false; }
        // if the call succeeded, owner must remain unchanged
        if (ok) {
            assertEq(c.owner(), ownerBefore, "owner changed after successful owned()");
        }
    }
}

